import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ad-performance-analyzer`,heroTitle:`Analyze ad performance across every channel`,heroSubtitle:`Perplexity Computer connects your ad platforms, surfaces lifts and drops, and delivers next actions for every campaign — automatically.`,heroOverlaySteps:[`Connecting to your ad platforms and reporting sheets`,`Analyzing performance trends, lifts, and drops across channels`,`Identifying conversion issues and untapped opportunities`,`Cross-channel performance brief with prioritized next actions — ready to execute`],generatingSteps:[`Pulling campaign data from your connected ad platforms and sheets`,`Designing an agent to detect lifts, drops, and conversion anomalies across every source`,`Configuring cross-channel opportunity scoring and budget recommendations`,`Setting up automated performance briefs with prioritized next actions`],featureSectionTitle:`From raw ad data to clear next actions`,featureCardTitles:[`Connects to your ad stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Google Sheets, Slack, Notion, Microsoft Power BI — Computer pulls from your ad platforms and reporting tools so every channel lands in one analysis.`,`Channel-by-channel performance scorecards. Conversion drop diagnostics. Budget reallocation recommendations. A prioritized action plan for every campaign.`],capabilitySectionTitle:`Your media analyst, on autopilot`,capabilitySectionSubtitle:`Connect your ad accounts, step away, get back a complete performance brief.`,capabilityCards:[{title:`Performance Detection`,description:`Computer can scan every campaign across channels — and flag exactly where spend is lifting results and where performance is declining.`},{title:`Conversion Diagnostics`,description:`Computer can trace conversion drops to specific creatives, audiences, or landing pages — and surface the root cause behind each issue.`},{title:`Channel Opportunities`,description:`Computer can compare cost-per-acquisition, ROAS, and saturation across channels — and recommend where to shift budget for maximum impact.`},{title:`Connect Your Tools`,description:`Computer can pull from Google Analytics, Google Sheets, Slack, Notion, and Microsoft Power BI — build workflows across your entire ad reporting stack.`},{title:`Remember & Learn`,description:`Computer can remember your benchmarks, past performance trends, and campaign history — so every analysis builds on what it already knows.`},{title:`Monitor & Alert`,description:`Computer can check your ad performance daily and alert you when a campaign spikes, drops, or hits a budget threshold you set.`}]});export{t as default};
